/** @nominal type:corpus:counter
 */
interface Counter {
  value: bigint;
}

pure function updateSharedRecord(): Seq<bigint> {
  let row: Counter = ({ value: 1n } satisfies Counter);
  let alias: Counter = row;
  alias.value = row.value + 1n;
  return seq<bigint>(matchResult(ok<Result<Counter, string>>(row), ok => ok.value, error => 0n), seqFold(seqMap(seq<bigint>(1n, 2n), increment), 0n, sum));
}

pure function increment(item: bigint): bigint {
  return item + 1n;
}

pure function sum(acc: bigint, item: bigint): bigint {
  return acc + item;
