// @module ledger
// @provenance prov:b3:79437a373ca618f292af3e7d893e0009c770538c0b8901d2689d24611ff662fd

/** @nominal type:currency:cents
 * @provenance prov:b3:79437a373ca618f292af3e7d893e0009c770538c0b8901d2689d24611ff662fd
 */
type Cents = bigint;

/** @nominal type:ledger:account
 * @provenance prov:b3:79437a373ca618f292af3e7d893e0009c770538c0b8901d2689d24611ff662fd
 */
interface Account {
  id: string;
  balance: Cents;
}

/**
 * @provenance prov:b3:70841ec96c9ae2bcf8ed01475bff395099276514faa73a6cbaf088b7c1b60267
 * @capability cap:db:ledger_append
 * @requires [sufficient_funds] sender.balance >= amount
 * @requires [positive_amount] amount > (1n as Cents)
 * @requires [distinct_accounts] sender.id !== receiver.id
 * @ensures [debit_exact] sender.balance === old(sender.balance) - amount
 * @ensures [credit_exact] receiver.balance === old(receiver.balance) + amount
 * @ensures [conservation] sender.balance + receiver.balance === old(sender.balance) + old(receiver.balance)
 * @modifies sender.balance, receiver.balance
 */
function transfer(sender: Account, receiver: Account, amount: Cents): void {
  sender.balance = sender.balance - amount;
  receiver.balance = receiver.balance + amount;
  invoke("cap:db:ledger_append", sender.id, receiver.id, amount);
  return undefined;
}

/**
 * @requires [non_negative_gross] gross >= (0n as Cents)
 * @ensures [non_negative_fee] result >= (0n as Cents)
 * @ensures [fee_within_gross] result <= gross
 * @ensures [fee_below_gross] !(gross > (0n as Cents)) || result < gross
 * @surface batchSize: range(1, 64, 1) minimize_latency = 8
 */
pure function feeFor(gross: Cents): Cents {
  return gross / 100n;
}

/**
 * @requires [non_negative_principal] principal >= (0n as Cents)
 * @requires [non_negative_periods] periods >= 0n
 * @requires [bounded_periods] periods <= 1200n
 * @ensures [never_shrinks] @property result >= principal
 */
pure function accrue(principal: Cents, periods: bigint): Cents {
  let total: Cents = principal;
  let i: bigint = 0n;
  /**
   * @invariant total >= principal
   * @invariant i >= 0n
   * @variant periods - i
   */
  while (i < periods) {
    total = total + total / 100n;
    i = i + 1n;
  }
  return total;
}

/**
 * @provenance prov:b3:70841ec96c9ae2bcf8ed01475bff395099276514faa73a6cbaf088b7c1b60267
 * @capability cap:db:ledger_append
 * @requires [sufficient_funds] payer.balance >= grossAmount
 * @requires [positive_amount] grossAmount > (0n as Cents)
 * @requires [distinct_accounts] payer.id !== payee.id
 * @modifies payer.balance, payee.balance
 * @surface cachePolicy: choice(lru, lfu, arc, none) minimize_latency = none
 */
function settle(payer: Account, payee: Account, grossAmount: Cents): void {
  let fee: Cents = feeFor(grossAmount);
  transfer(payer, payee, grossAmount - fee);
  return undefined;
}

