// @module module

pure function write(record: Box): void {
  record.value = 12n;
  return undefined;
}

/**
 * @capability cap:test:emit
 */
function fail(record: Box): void {
  let local: bigint = 1n;
  atomic {
    local = 20n;
    record.value = 9n;
    invoke("cap:test:emit", record);
    write(record);
    let allocated: Box = ({ value: 50n } satisfies Box);
    invoke("cap:test:emit", allocated);
    assert(false, "atomic-fault");
  }
}

pure function normal(record: Box): bigint {
  atomic {
    record.value = 2n;
    atomic {
      record.value = 3n;
    }
  }
  record.value = 4n;
  return record.value;
}

pure function returned(record: Box): bigint {
  let local: bigint = 1n;
  atomic {
    local = 3n;
    atomic {
      record.value = 7n;
      while (true) {
        return record.value + local;
      }
    }
    record.value = 99n;
  }
  return 99n;
}

/**
 * @ensures [post-return] false
 */
pure function postFail(record: Box): bigint {
  atomic {
    record.value = 8n;
    return 8n;
  }
  return 0n;
}

pure function outerPostFail(record: Box): void {
  atomic {
    record.value = 2n;
    postFail(record);
  }
}

pure function innerFail(record: Box): void {
  atomic {
    record.value = 2n;
    atomic {
      record.value = 3n;
      assert(false, "atomic-fault");
    }
  }
}

pure function returnFault(record: Box): bigint {
  atomic {
    record.value = 5n;
    return 1n / 0n;
  }
  return 0n;
}

pure function overflow(record: Box): void {
  atomic {
    record.value = 6n;
    intCast<IntN<8, signed, trap>>(128n);
  }
}

pure function allocate(): Box {
  return ({ value: 99n } satisfies Box);
}

/**
 * @capability cap:test:emit
 */
function makeTask(): Task<Box> {
  return spawn(taskWork());
}

/**
 * @capability cap:test:emit
 */
function taskWork(): Box {
  invoke("cap:test:emit", 1n);
  return ({ value: 60n } satisfies Box);
}

/**
 * @capability cap:test:emit
 */
function awaitFail(task: Task<Box>): void {
  atomic {
    let allocated: Box = awaitTask(task);
    assert(false, "atomic-fault");
  }
}

/**
 * @capability cap:test:emit
 */
function awaitTask(task: Task<Box>): Box {
  return awaitTask(task);
}

/**
 * @capability cap:test:emit
 */
function revoke(record: Box): void {
  atomic {
    record.value = 10n;
    invoke("cap:test:emit", 1n);
    record.value = 12n;
    invoke("cap:test:emit", 2n);
  }
}

